/**
 * Background music. tracks.json is generated by scripts/analyze-tracks.ts
 * from scripts/track-sources.ts (licences checked on each item's page).
 * Every track streams unmodified from its host; `gainDb` is applied as
 * player volume, never by editing the file (CC BY-NC-ND forbids changes).
 */
import tracks from './tracks.json';

export type Era = 'traditional' | 'modern';

/** Licences that allow streaming on our non-commercial site (decided with Ofek, Round 3). */
export const ALLOWED_LICENSES = [
  'PD',
  'CC0',
  'CC BY 3.0',
  'CC BY 4.0',
  'CC BY-SA 3.0',
  'CC BY-SA 4.0',
  'FAL 1.3',
  'CC BY-NC 4.0',
  'CC BY-NC-SA 3.0',
  'CC BY-NC-ND 2.5',
  'CC BY-NC-ND 3.0',
  'CC BY-NC-ND 4.0',
] as const;
export type License = (typeof ALLOWED_LICENSES)[number];

export interface Track {
  id: string;
  title: string;
  artist: string;
  era: Era;
  style: string;
  src: string;
  license: License;
  licenseUrl: string | null;
  sourceUrl: string;
  attribution: string;
  durationS: number;
  loudnessLufs: number;
  /** ≤ 0: how much to turn this track down to match the others. */
  gainDb: number;
  /** When the URL was last confirmed to stream. */
  checkedOn: string;
}

export const TRACKS = tracks as Track[];

export const findTrack = (id: string) => TRACKS.find((t) => t.id === id);
